const trig = $('When Orchestrator Requests Stakeholder Update')
  .first().json;

const item = $input.first()?.json ?? {};

const base = {
  agent: 'stakeholder_update',
  snapshot_id: trig.snapshot_id || '',
  generated_at: new Date().toISOString()
};

const fail = (message) => [{
  json: {
    ...base,
    status: 'error',
    update: null,
    error_detail: String(message).slice(0, 4000)
  }
}];

if (item.error) {
  return fail(item.error.message || item.error);
}

// Parse JSON strings and structured objects.
function parseValue(value) {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === 'object') {
    return value;
  }

  const text = String(value)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

let parsed = parseValue(
  item.output !== undefined
    ? item.output
    : item.text !== undefined
      ? item.text
      : item
);

if (!parsed || typeof parsed !== 'object' ||
    Array.isArray(parsed)) {
  return fail('Invalid stakeholder JSON output.');
}

// Support common n8n output wrappers.
if (parsed.output !== undefined) {
  parsed = parseValue(parsed.output);
}

if (!parsed || typeof parsed !== 'object' ||
    Array.isArray(parsed)) {
  return fail('Invalid stakeholder output structure.');
}

// Support nested update objects.
const data = parsed.update &&
  typeof parsed.update === 'object' &&
  !Array.isArray(parsed.update)
    ? parsed.update
    : parsed;

const reportedStatus = String(
  parsed.status || data.status || ''
).toLowerCase();

if (['error', 'failed', 'failure'].includes(reportedStatus)) {
  return fail(
    parsed.error_detail ||
    data.error_detail ||
    'Stakeholder agent reported an error.'
  );
}

const asString = value =>
  typeof value === 'string'
    ? value.trim()
    : '';

const asArray = value =>
  Array.isArray(value)
    ? value
    : [];

const validHealth = [
  'GREEN',
  'AMBER',
  'RED',
  'UNKNOWN'
];

const health = asString(
  data.current_status
).toUpperCase();

const update = {
  project_name: asString(data.project_name),

  audience: asString(data.audience) ||
    'Project stakeholders',

  sprint: asString(data.sprint) || null,

  subject: asString(data.subject),

  body: asString(data.body),

  reporting_period:
    asString(data.reporting_period) || null,

  executive_summary: asString(
    data.executive_summary || data.summary
  ),

  current_status: validHealth.includes(health)
    ? health
    : 'UNKNOWN',

  accomplishments: asArray(
    data.accomplishments
  ),

  upcoming_activities: asArray(
    data.upcoming_activities
  ),

  risks_and_blockers: asArray(
    data.risks_and_blockers
  ),

  decisions_needed: asArray(
    data.decisions_needed
  ),

  action_items: asArray(
    data.action_items
  ),

  source_references: asArray(
    data.source_references ??
    parsed.source_references
  ).filter(ref =>
    typeof ref === 'string' && ref.trim()
  ),

  data_gaps: asArray(
    data.data_gaps
  ),

  draft_only: true
};

// Required communication fields.
if (!update.subject) {
  return fail('Missing stakeholder email subject.');
}

if (!update.body) {
  return fail('Missing stakeholder email body.');
}

if (!update.executive_summary) {
  return fail('Missing executive summary.');
}

// Require evidence references for factual updates.
const hasProjectClaims = [
  update.executive_summary,
  ...update.accomplishments,
  ...update.upcoming_activities,
  ...update.risks_and_blockers,
  ...update.action_items
].some(value => {
  if (typeof value === 'string') {
    return value.trim().length > 0;
  }
  return value !== null && typeof value === 'object';
});

if (
  hasProjectClaims &&
  update.source_references.length === 0
) {
  return fail(
    'Source references missing from stakeholder update.'
  );
}

// Validate snapshot consistency.
const returnedSnapshot =
  parsed.snapshot_id ||
  data.snapshot_id ||
  '';

if (
  returnedSnapshot &&
  base.snapshot_id &&
  returnedSnapshot !== base.snapshot_id
) {
  return fail(
    'Snapshot mismatch between stakeholder ' +
    'output and orchestrator request.'
  );
}

return [{
  json: {
    ...base,
    status: 'ok',
    update
  }
}];
